DROP TABLE IF EXISTS payments CASCADE;
CREATE TABLE payments (id bigint PRIMARY KEY, merchant_id int, currency text,
                       amount_cents bigint, created_at timestamptz);
INSERT INTO payments
  SELECT g, 1 + (g * 7919) % 2000,
         (ARRAY['EUR','EUR','EUR','GBP','USD','SEK'])[1 + (g * 31) % 6],
         (g * 104729) % 100000,
         TIMESTAMPTZ '2026-10-01 00:00+00' + g * interval '1 second'
  FROM generate_series(1, 1000000::bigint) g;
VACUUM ANALYZE payments;
SET max_parallel_workers_per_gather = 0;

-- 1. the dashboard's question, straight from the table
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF)
SELECT (created_at AT TIME ZONE 'UTC')::date AS day, count(*) AS n, sum(amount_cents) AS sum_cents
FROM payments WHERE merchant_id = 42 GROUP BY 1 ORDER BY 1;

-- 2. store the answer for every merchant and day
\timing on
CREATE MATERIALIZED VIEW daily_totals AS
SELECT merchant_id, (created_at AT TIME ZONE 'UTC')::date AS day,
       count(*) AS n, sum(amount_cents) AS sum_cents
FROM payments GROUP BY 1, 2;
\timing off
CREATE INDEX ON daily_totals (merchant_id);
ANALYZE daily_totals;

-- 3. the same question, from the view
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF)
SELECT day, n, sum_cents FROM daily_totals WHERE merchant_id = 42 ORDER BY day;

-- 4. a new payment for merchant 42: the view doesn't see it until a refresh
INSERT INTO payments VALUES (1000001, 42, 'EUR', 99900, TIMESTAMPTZ '2026-10-01 12:00+00');
SELECT n, sum_cents FROM daily_totals WHERE merchant_id = 42 AND day = '2026-10-01';
\timing on
REFRESH MATERIALIZED VIEW daily_totals;
\timing off
SELECT n, sum_cents FROM daily_totals WHERE merchant_id = 42 AND day = '2026-10-01';

-- 1. CONCURRENTLY needs a unique index to match old rows with new ones
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_totals;
CREATE UNIQUE INDEX daily_totals_key ON daily_totals (merchant_id, day);

-- 2. which lock does each kind of refresh hold while it runs?
BEGIN;
REFRESH MATERIALIZED VIEW daily_totals;
SELECT mode FROM pg_locks WHERE relation = 'daily_totals'::regclass AND granted;
ROLLBACK;
BEGIN;
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_totals;
SELECT mode FROM pg_locks WHERE relation = 'daily_totals'::regclass AND granted;
ROLLBACK;

-- 3. one changed payment, then each refresh, timed
UPDATE payments SET amount_cents = amount_cents + 100 WHERE id = 1000001;
\timing on
REFRESH MATERIALIZED VIEW daily_totals;
REFRESH MATERIALIZED VIEW CONCURRENTLY daily_totals;
\timing off

