CREATE MATERIALIZED VIEW merchant_totals AS
SELECT merchant_id, count(*) AS n, sum(amount_cents) AS sum_cents
FROM payments GROUP BY merchant_id;
CREATE UNIQUE INDEX ON merchant_totals (merchant_id);

-- a job, every few minutes: reruns the whole query,
-- then applies the differences while readers keep reading
REFRESH MATERIALIZED VIEW CONCURRENTLY merchant_totals;

